-- +migrate Up
-- Vision of Greatness (arc 9) mission content from the EVE University wiki.
INSERT INTO `missionObjectives` (`missionID`,`briefingID`,`objectiveType`,`itemTypeID`,`itemQty`,`npcCount`,`npcFactionID`,`structureTypeID`,`structureQty`,`objectiveText`,`briefingText`,`note`) VALUES
  (80189, 0, 1, 0, 0, 0, 0, 0, 0, 'Report to: Holorelay: Heika Torigo', 'Capsuleer, how would you like to time-travel? <br><br>No, of course not literally, but with the help of AIR’s new advancements in holographics and coordinated drone actors, you can take a step out of the present and into the epic battles of the past!<br><br>Each experience has been crafted in cooperation with the Empire’s top military experts. Yes, perhaps they are more… cinematic, some might even say biased, than historical.. but that is what makes them such an incredible insight into the minds of the Empires! <br><br>Accept this offer, visit all four holographic agents and their simulated experiences, and learn the Empire’s truths for yourself!', 'VOG_Holographic_Reenactment'),
  (80190, 0, 1, 0, 0, 0, 0, 0, 0, '', 'The Caldari State welcomes your interest in our history. This experience will show you why we fight, and why you should join us. Learn the meaning of honor, of duty, of what it means to be Caldari, as you experience our greatest loss and our most epic triumph.<br><br>Travel to the simulation site. Once you arrive, we will speak again.', 'VOG_Caldari_Prime_Breakout'),
  (80191, 0, 1, 0, 0, 0, 0, 0, 0, 'Report to Holorelay: Kanth Filmir', 'You can travel to the next simulation now, and see how well the State stands up by comparison. I believe it is some foolishness made by the tribes of the Minmatar Republic.', 'VOG_Travel_to_Minmatar'),
  (80192, 0, 1, 0, 0, 0, 0, 0, 0, '', 'Understanding heritage is at the heart of what it means to be Minmatar. Join us in a simulation of the day our Republic was born, the legendary Battle of Pator.<br><br>Travel to the simulation site. I will explain more once you arrive.', 'VOG_Battle_of_Pator'),
  (80193, 0, 1, 0, 0, 0, 0, 0, 0, 'Report to Holorelay: Sirdan xer Qosh', 'The next simulation in this series is the lies and propaganda of the Amarr Empire. Travel to their Imperial mouthpiece and see what they have to say for themselves. I suggest you study it carefully to better understand the enemy.', 'VOG_Travel_to_Amarr'),
  (80194, 0, 1, 0, 0, 0, 0, 0, 0, '', 'Our past is but a stepping stone to our inevitable destiny and our rightful dominion over the stars. This simulation is a pale mirror of the glorious light of that destiny.
and yet it shines so bright

Travel to the simulation site, and I shall instruct you as you feel the power of our faith.', 'VOG_Golgothan_Fields'),
  (80195, 0, 1, 0, 0, 0, 0, 0, 0, 'Report to Holorelay: Foriana Revelli', 'Your final simulation will be some hollow entertainment put together by the godless Federation. Go and bear witness to the emptiness of their words, so that you may return to the Empire with a deeper understanding of the power of faith.', 'VOG_Travel_to_the_Gallente'),
  (80196, 0, 1, 0, 0, 0, 0, 0, 0, '', 'The battle for freedom is a battle we must fight every day. In this simulation, you’ll learn just what it means to fight on the right side of history.<br><br>Travel to the simulation site, and let’s go on a journey of justice together.', 'VOG_Intaki_Liberation')
ON DUPLICATE KEY UPDATE objectiveType=VALUES(objectiveType), objectiveText=VALUES(objectiveText), briefingText=VALUES(briefingText), note=VALUES(note);
-- +migrate Down
DELETE FROM `missionObjectives` WHERE `missionID` BETWEEN 80189 AND 80196;
